#[derive(Clone, Copy, Debug)]
struct ReferenceWeight {
    w: f64,
    dw_dq: f64,
    d2w_dq2: f64,
    dw_dcn: f64,
    d2w_dcn2: f64,
}

#[derive(Clone, Copy, Debug, Default)]
pub struct D4C6CnDerivatives {
    pub c6: f64,
    pub dc6_dcni: f64,
    pub dc6_dcnj: f64,
    pub d2c6_dcni2: f64,
    pub d2c6_dcni_dcnj: f64,
    pub d2c6_dcnj2: f64,
}

#[derive(Clone, Copy, Debug, Default)]
pub struct D4C6ChargeDerivatives {
    pub c6: f64,
    pub dc6_dqi: f64,
    pub dc6_dqj: f64,
    pub d2c6_dqi2: f64,
    pub d2c6_dqi_dqj: f64,
    pub d2c6_dqj2: f64,
}

#[inline]
pub fn has_d4_reference_data(z: u8) -> bool {
    let z = z as usize;
    z > 0 && z <= ZMAX && REFN[z] > 0
}

#[inline]
pub fn d4_r4r2_atom(z: u8) -> Result<f64> {
    let z = z as usize;
    if z == 0 || z > ZMAX || R4R2[z] <= 0.0 {
        return Err(Gfn1Error::InvalidInput(format!(
            "DFT-D4 r4/r2 data missing for Z={}",
            z
        )));
    }
    Ok(R4R2[z])
}

/// Per-atom DFT-D4 reference-state weights (and their charge/CN derivatives).
/// Opaque wrapper so the inner [`ReferenceWeight`] layout stays private. These
/// depend only on a single atom's (Z, charge, CN), so they can be precomputed
/// once per atom and reused across every pair instead of being rebuilt O(nat) times.
#[derive(Clone, Copy, Debug)]
pub struct D4AtomWeights {
    weights: [ReferenceWeight; RMAX + 1],
}

/// Build the reference-state weights for one atom (validates the element).
pub fn d4_atom_reference_weights(z: u8, q: f64, cn: f64) -> Result<D4AtomWeights> {
    Ok(D4AtomWeights {
        weights: reference_weights(z as usize, q, cn)?,
    })
}

/// C6 and its charge/CN derivatives for a pair, from precomputed per-atom weights.
/// Identical arithmetic to [`d4_c6_with_derivatives`]; callers that already hold the
/// per-atom weights avoid recomputing them.
/// Opaque handle to the cached DFT-D4 C6 reference table for one element pair.
/// Fetch it once (outside hot/parallel loops) with [`d4_c6_pair_table`]; it carries
/// the `Arc` so the global pair-table cache lock is never touched again.
#[derive(Clone)]
pub struct D4C6PairTable(Arc<[[f64; RMAX + 1]; RMAX + 1]>);

/// Fetch (and lazily cache) the C6 reference table for element pair `(zi, zj)`.
/// Acquires the global cache `Mutex` once; callers prefetch the few distinct element
/// pairs OUTSIDE the O(nat^2) C6 loop so the inner loop (and its parallel workers)
/// never contend on that lock.
pub fn d4_c6_pair_table(zi: u8, zj: u8) -> D4C6PairTable {
    D4C6PairTable(reference_c6_pair_table(zi as usize, zj as usize))
}

/// C6 + charge/CN derivatives from precomputed per-atom weights and a prefetched pair
/// table. Lock-free, so it is safe (and fast) to call from parallel workers.
pub fn d4_c6_from_atom_weights_with_table(
    zi: u8,
    zj: u8,
    wi: &D4AtomWeights,
    wj: &D4AtomWeights,
    table: &D4C6PairTable,
) -> (f64, f64, f64, f64, f64) {
    let zi_us = zi as usize;
    let zj_us = zj as usize;
    let wi = &wi.weights;
    let wj = &wj.weights;
    let t = &table.0;
    let mut c6 = 0.0;
    let mut dc6_dqi = 0.0;
    let mut dc6_dqj = 0.0;
    let mut dc6_dcni = 0.0;
    let mut dc6_dcnj = 0.0;
    for ir in 1..=REFN[zi_us] {
        for jr in 1..=REFN[zj_us] {
            let c6_ref = t[ir][jr];
            c6 += wi[ir].w * wj[jr].w * c6_ref;
            dc6_dqi += wi[ir].dw_dq * wj[jr].w * c6_ref;
            dc6_dqj += wi[ir].w * wj[jr].dw_dq * c6_ref;
            dc6_dcni += wi[ir].dw_dcn * wj[jr].w * c6_ref;
            dc6_dcnj += wi[ir].w * wj[jr].dw_dcn * c6_ref;
        }
    }
    (c6, dc6_dqi, dc6_dqj, dc6_dcni, dc6_dcnj)
}

/// C6 value only from precomputed per-atom weights and a prefetched pair table.
/// This is the hot SCC-energy path; it avoids accumulating charge/CN derivatives
/// when the D4 scalar potential is not needed.
pub fn d4_c6_value_from_atom_weights_with_table(
    zi: u8,
    zj: u8,
    wi: &D4AtomWeights,
    wj: &D4AtomWeights,
    table: &D4C6PairTable,
) -> f64 {
    let zi_us = zi as usize;
    let zj_us = zj as usize;
    let wi = &wi.weights;
    let wj = &wj.weights;
    let t = &table.0;
    let mut c6 = 0.0;
    for ir in 1..=REFN[zi_us] {
        for jr in 1..=REFN[zj_us] {
            c6 += wi[ir].w * wj[jr].w * t[ir][jr];
        }
    }
    c6
}

pub fn d4_c6_from_atom_weights(
    zi: u8,
    zj: u8,
    wi: &D4AtomWeights,
    wj: &D4AtomWeights,
) -> (f64, f64, f64, f64, f64) {
    let table = d4_c6_pair_table(zi, zj);
    d4_c6_from_atom_weights_with_table(zi, zj, wi, wj, &table)
}

pub fn d4_c6_with_derivatives(
    zi: u8,
    zj: u8,
    qi: f64,
    qj: f64,
    cni: f64,
    cnj: f64,
) -> Result<(f64, f64, f64, f64, f64)> {
    let wi = d4_atom_reference_weights(zi, qi, cni)?;
    let wj = d4_atom_reference_weights(zj, qj, cnj)?;
    Ok(d4_c6_from_atom_weights(zi, zj, &wi, &wj))
}

pub fn d4_c6_with_cn_derivatives2(
    zi: u8,
    zj: u8,
    qi: f64,
    qj: f64,
    cni: f64,
    cnj: f64,
) -> Result<D4C6CnDerivatives> {
    let zi_us = zi as usize;
    let zj_us = zj as usize;
    validate_element(zi_us)?;
    validate_element(zj_us)?;
    let wi = reference_weights(zi_us, qi, cni)?;
    let wj = reference_weights(zj_us, qj, cnj)?;
    let mut out = D4C6CnDerivatives::default();
    for ir in 1..=REFN[zi_us] {
        for jr in 1..=REFN[zj_us] {
            let c6_ref = reference_c6(zi_us, ir, zj_us, jr);
            out.c6 += wi[ir].w * wj[jr].w * c6_ref;
            out.dc6_dcni += wi[ir].dw_dcn * wj[jr].w * c6_ref;
            out.dc6_dcnj += wi[ir].w * wj[jr].dw_dcn * c6_ref;
            out.d2c6_dcni2 += wi[ir].d2w_dcn2 * wj[jr].w * c6_ref;
            out.d2c6_dcni_dcnj += wi[ir].dw_dcn * wj[jr].dw_dcn * c6_ref;
            out.d2c6_dcnj2 += wi[ir].w * wj[jr].d2w_dcn2 * c6_ref;
        }
    }
    Ok(out)
}

pub fn d4_c6_with_charge_derivatives2(
    zi: u8,
    zj: u8,
    qi: f64,
    qj: f64,
    cni: f64,
    cnj: f64,
) -> Result<D4C6ChargeDerivatives> {
    let zi_us = zi as usize;
    let zj_us = zj as usize;
    validate_element(zi_us)?;
    validate_element(zj_us)?;
    let wi = reference_weights(zi_us, qi, cni)?;
    let wj = reference_weights(zj_us, qj, cnj)?;
    let mut out = D4C6ChargeDerivatives::default();
    for ir in 1..=REFN[zi_us] {
        for jr in 1..=REFN[zj_us] {
            let c6_ref = reference_c6(zi_us, ir, zj_us, jr);
            out.c6 += wi[ir].w * wj[jr].w * c6_ref;
            out.dc6_dqi += wi[ir].dw_dq * wj[jr].w * c6_ref;
            out.dc6_dqj += wi[ir].w * wj[jr].dw_dq * c6_ref;
            out.d2c6_dqi2 += wi[ir].d2w_dq2 * wj[jr].w * c6_ref;
            out.d2c6_dqi_dqj += wi[ir].dw_dq * wj[jr].dw_dq * c6_ref;
            out.d2c6_dqj2 += wi[ir].w * wj[jr].d2w_dq2 * c6_ref;
        }
    }
    Ok(out)
}

#[inline]
fn validate_element(z: usize) -> Result<()> {
    if z == 0 || z > ZMAX || REFN[z] == 0 {
        Err(Gfn1Error::InvalidInput(format!(
            "DFT-D4 reference data missing for Z={}",
            z
        )))
    } else {
        Ok(())
    }
}

fn reference_weights(z: usize, q: f64, cn: f64) -> Result<[ReferenceWeight; RMAX + 1]> {
    validate_element(z)?;
    let mut out = [ReferenceWeight {
        w: 0.0,
        dw_dq: 0.0,
        d2w_dq2: 0.0,
        dw_dcn: 0.0,
        d2w_dcn2: 0.0,
    }; RMAX + 1];
    let nref = REFN[z];
    let ngw = reference_gaussian_counts(z);
    let mut norm = 0.0;
    let mut dnorm = 0.0;
    let mut d2norm = 0.0;
    for ir in 1..=nref {
        for igw in 1..=ngw[ir] {
            let wf = (igw as f64) * WF;
            let (gw, dgw, d2gw) = weight_cn_derivatives(wf, cn, REFCOVCN[z][ir]);
            norm += gw;
            dnorm += dgw;
            d2norm += d2gw;
        }
    }
    let eps_norm = f64::MIN_POSITIVE.sqrt();
    let norm_inv = if norm.abs() > eps_norm {
        1.0 / norm
    } else {
        0.0
    };
    let zi_eff = ZEFF[z];
    let gi = HARDNESS[z] * GC;
    let mut maxcn = REFCOVCN[z][1];
    for ir in 2..=nref {
        maxcn = maxcn.max(REFCOVCN[z][ir]);
    }
    for ir in 1..=nref {
        let mut expw = 0.0;
        let mut expd = 0.0;
        let mut expd2 = 0.0;
        for igw in 1..=ngw[ir] {
            let wf = (igw as f64) * WF;
            let (gw, dgw, d2gw) = weight_cn_derivatives(wf, cn, REFCOVCN[z][ir]);
            expw += gw;
            expd += dgw;
            expd2 += d2gw;
        }
        let mut gwk = expw * norm_inv;
        let mut dgwk = norm_inv * (expd - expw * dnorm * norm_inv);
        let mut d2gwk = expd2 * norm_inv
            - expw * d2norm * norm_inv * norm_inv
            - 2.0 * expd * dnorm * norm_inv * norm_inv
            + 2.0 * expw * dnorm * dnorm * norm_inv * norm_inv * norm_inv;
        if !gwk.is_finite() || norm_inv == 0.0 {
            gwk = if (maxcn - REFCOVCN[z][ir]).abs() < 1.0e-12 {
                1.0
            } else {
                0.0
            };
        }
        if !dgwk.is_finite() || norm_inv == 0.0 {
            dgwk = 0.0;
        }
        if !d2gwk.is_finite() || norm_inv == 0.0 {
            d2gwk = 0.0;
        }
        let qref = REFQ[z][ir] + zi_eff;
        let qmod = q + zi_eff;
        let zeta_val = zeta(GA, gi, qref, qmod);
        let dzeta_val = dzeta(GA, gi, qref, qmod);
        let d2zeta_val = d2zeta(GA, gi, qref, qmod);
        out[ir] = ReferenceWeight {
            w: gwk * zeta_val,
            dw_dq: gwk * dzeta_val,
            d2w_dq2: gwk * d2zeta_val,
            dw_dcn: dgwk * zeta_val,
            d2w_dcn2: d2gwk * zeta_val,
        };
    }
    Ok(out)
}

fn reference_gaussian_counts(z: usize) -> [usize; RMAX + 1] {
    let mut ngw = [1_usize; RMAX + 1];
    let mut cnc = [0_usize; 20];
    cnc[0] = 1;
    let nref = REFN[z];
    for ir in 1..=nref {
        let mut icn = REFCN_LEGACY[z][ir].round() as isize;
        if icn < 0 {
            icn = 0;
        }
        let icn = (icn as usize).min(19);
        cnc[icn] += 1;
    }
    for ir in 1..=nref {
        let mut icn = REFCN_LEGACY[z][ir].round() as isize;
        if icn < 0 {
            icn = 0;
        }
        let icn = (icn as usize).min(19);
        let count = cnc[icn];
        ngw[ir] = count * (count + 1) / 2;
    }
    ngw
}

static C6_PAIR_CACHE: OnceLock<Mutex<HashMap<u16, Arc<[[f64; RMAX + 1]; RMAX + 1]>>>> =
    OnceLock::new();

fn reference_c6(zi: usize, ir: usize, zj: usize, jr: usize) -> f64 {
    reference_c6_pair_table(zi, zj)[ir][jr]
}

fn reference_c6_pair_table(zi: usize, zj: usize) -> Arc<[[f64; RMAX + 1]; RMAX + 1]> {
    // Provenance: these pair tables are the DFT-D4 reference C6 values used by
    // d4_c6_with_derivatives(). They are independent of molecular geometry,
    // charge and CN. Cache them lazily per element pair instead of precomputing
    // the full 118x118 element table.
    let key = ((zi as u16) << 8) | (zj as u16);
    let cache = C6_PAIR_CACHE.get_or_init(|| Mutex::new(HashMap::new()));
    if let Some(found) = cache
        .lock()
        .expect("D4 C6 pair cache lock poisoned")
        .get(&key)
        .cloned()
    {
        return found;
    }
    let mut table = [[0.0_f64; RMAX + 1]; RMAX + 1];
    for ir in 1..=REFN[zi] {
        for jr in 1..=REFN[zj] {
            table[ir][jr] = reference_c6_uncached(zi, ir, zj, jr);
        }
    }
    let table = Arc::new(table);
    let mut guard = cache.lock().expect("D4 C6 pair cache lock poisoned");
    if let Some(found) = guard.get(&key).cloned() {
        return found;
    }
    guard.insert(key, table.clone());
    table
}

fn reference_c6_uncached(zi: usize, ir: usize, zj: usize, jr: usize) -> f64 {
    let mut pol = [0.0_f64; FREQ];
    for n in 0..FREQ {
        pol[n] = reference_alpha(zi, ir, n) * reference_alpha(zj, jr, n);
    }
    THOPI * trapzd(&pol)
}

fn reference_alpha(z: usize, ir: usize, freq: usize) -> f64 {
    let is = REFSYS[z][ir];
    if is == 0 || is > SMAX {
        return 0.0;
    }
    let iz = ZEFF[is];
    let aiw_sec = SSCALE[is] * SECAIW[is][freq] * zeta(GA, HARDNESS[is] * GC, iz, REFH[z][ir] + iz);
    let raw = ASCALE[z][ir] * (ALPHAIW[z][ir][freq] - HCOUNT[z][ir] * aiw_sec);
    raw.max(0.0)
}

#[inline]
fn weight_cn(wf: f64, cn: f64, cnref: f64) -> f64 {
    (-(wf) * (cn - cnref).powi(2)).exp()
}

fn weight_cn_derivatives(wf: f64, cn: f64, cnref: f64) -> (f64, f64, f64) {
    let delta = cn - cnref;
    let value = weight_cn(wf, cn, cnref);
    let first = -2.0 * wf * delta * value;
    let second = (4.0 * wf * wf * delta * delta - 2.0 * wf) * value;
    (value, first, second)
}

#[inline]
fn zeta(a: f64, c: f64, qref: f64, qmod: f64) -> f64 {
    if qmod < 0.0 {
        a.exp()
    } else {
        (a * (1.0 - (c * (1.0 - qref / qmod)).exp())).exp()
    }
}

#[inline]
fn dzeta(a: f64, c: f64, qref: f64, qmod: f64) -> f64 {
    if qmod < 0.0 {
        0.0
    } else {
        let inner = (c * (1.0 - qref / qmod)).exp();
        -a * c * inner * zeta(a, c, qref, qmod) * qref / (qmod * qmod)
    }
}

#[inline]
fn d2zeta(a: f64, c: f64, qref: f64, qmod: f64) -> f64 {
    if qmod < 0.0 {
        0.0
    } else {
        let inner = (c * (1.0 - qref / qmod)).exp();
        let z = zeta(a, c, qref, qmod);
        let q2 = qmod * qmod;
        let b = -a * c * qref * inner / q2;
        let bp = -a * c * qref * inner * (c * qref / (q2 * q2) - 2.0 / (q2 * qmod));
        z * (b * b + bp)
    }
}

#[inline]
fn trapzd(pol: &[f64; FREQ]) -> f64 {
    let mut sum = 0.0;
    for i in 0..FREQ {
        sum += pol[i] * TRAPZD_WEIGHTS[i];
    }
    sum
}
